<?php require 'includes/config.php';$pageTitle='Cart';if(isset($_GET['remove']))unset($_SESSION['cart'][(int)$_GET['remove']]);if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['update'])){foreach($_POST['qty']??[] as $id=>$q){if(isset($_SESSION['cart'][$id]))$_SESSION['cart'][$id]['qty']=max(1,(int)$q);}}$cart=$_SESSION['cart']??[];$total=0;foreach($cart as $i)$total+=$i['price']*$i['qty'];include 'includes/header.php';?>
<section class="page-hero"><div class="container"><span class="eyebrow">Your bag</span><h1>Shopping cart</h1></div></section><section class="section"><div class="container"><?php if(!$cart):?><div class="empty-state"><h2>Your cart is empty</h2><p>Add products from the shop to continue.</p><a class="btn" href="shop.php">Go shopping</a></div><?php else:?><form method="post"><table class="cart-table"><tr><th>Image</th><th>Product</th><th>Price</th><th>Qty</th><th>Total</th><th></th></tr><?php foreach($cart as $i):?><tr><td><img class="cart-thumb" src="<?=e($i['image'])?>"></td><td><?=e($i['name'])?></td><td>LKR <?=number_format($i['price'],2)?></td><td><input class="qty" type="number" min="1" name="qty[<?=$i['id']?>]" value="<?=$i['qty']?>"></td><td>LKR <?=number_format($i['price']*$i['qty'],2)?></td><td><a href="cart.php?remove=<?=$i['id']?>">Remove</a></td></tr><?php endforeach;?></table><div style="margin-top:15px"><button class="btn btn-outline" name="update">Update cart</button></div></form><div class="cart-summary"><div class="summary-row"><span>Subtotal</span><strong>LKR <?=number_format($total,2)?></strong></div><div class="summary-row"><span>Delivery</span><strong><?=$total>=15000?'FREE':'LKR 750.00'?></strong></div><?php $grand=$total+($total>=15000?0:750);?><div class="summary-row total"><span>Total</span><span>LKR <?=number_format($grand,2)?></span></div><a class="btn" style="width:100%" href="checkout.php">Proceed to checkout</a></div><?php endif;?></div></section><?php include 'includes/footer.php';?>
